item.content:encoded:
.custom-logo-link img{
	width:250px ;
	height:200px;
	margin: 0px !important;
}
.site-description{
	width:250px ;
	margin: 0px !important;
}
.social-navigation{
	display:none;
	width:0px;
}
.site-branding{
	float:left;
	width:70%;
	text-align:left !important;
	margin: 0px !important;
}
.menu-toggle{
	margin-right:20px !important;
}


.site-header-right-wrapper{
	float:right;
	width:100%;
	text-align: right;
  padding-top: 0px;
	position:absolute;
}

.site-header-main {
	display: block; 
}

#header-navigation-area{
    position:absolute;
		float: right;
    width: 100%;
    text-align: right;
	top:0px !important;
}
.home header.site-header {
    height: 300px;
    background-color: #69c3f0;
}
.home  .site-description {
    color: white;
}
.hero-content-wrapper header{
padding-top: 100px;
}
.custom-header-content{
	padding-top:0px !important;
}
.home .site-navigation a{
	color:black !important;
}



.wp-block-post-featured-image img {
    width: 250px;
    height: 250px;
	margin-top: 20px;
}
.menu-primary-toggle{
	float:right;
}
@media (max-width: 1023px) {
.menu-toggle, #header-navigation-area, .menu-primary-toggle{
	border:none !important;
	top:100px !important;
}
	.site-header-right-wrapper .search-container{
	width:30%;
	text-align: right;
    margin-right: 50px;
    float: right;
}

	.site-primary-menu{
	float:right;
	width:50%;
	text-align: right !important;
	    z-index: 100;
    position: absolute !important;
    top: 60px;
	left:48%;
	background-color: rgba(105, 195, 240, 0.9);
}
}


@media (min-width: 1023px) {
.secondary-search-wrapper{
	    padding-right: 80px;
	    z-index: 200;
}
#search-container-main .search-container.toggled-on {
    display: block;
	margin-top:20px;
    margin-right: 80px;
}
	.home .site-navigation{
	 margin-right: 40px;
}
		.primary-nav-center .site-primary-menu{
	text-align: right !important;

	}
}
.home .custom-logo-link img {
    filter: contrast(200%);
}
@media (max-width: 576px){

	.custom-logo-link img {
    width: 150px;
    height: 100px;
	}
	.site-description{
		display:none;
	}


}

.site-title{
	display:none;
}
.page-id-587 .wp-block-post-featured-image img, .page-id-56 .wp-block-post-featured-image img {
    width: 550px !important;
    height: 550px  !important;
}

.wp-block-group__inner-container p{
	font-size:42px !important;
}

.site-footer .footer-widget-area {
    padding: 0px;
}
.footer-widget-4{
	text-align:center; 
	width:100% !important;
	background-color: white;
}
